-- tests/inventario/autoconteo-noche-siembra.sql · Las 23 filas como se midieron en producción el 21/10 (cuenta, estado, líneas contadas; las notas, inventadas).
create table public._foto_siembra as select md5(string_agg(id || status || coalesce(notes, '') || updated_at, '|' order by id)) m from public.inventory_count;
